from fastapi import APIRouter, Depends, HTTPException, status
import hvac

router = APIRouter(prefix="/security/totp")

@router.get("/{key_name}/current-code")
async def get_vault_totp_code(
    key_name: str,
    vault_client: hvac.Client = Depends(get_vault_client),
    user: User = Depends(get_current_user)
):
    expected_key_name = f"totp_user_{user.id}"
    if key_name != expected_key_name and not user.is_security_officer:
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail="Cannot access TOTP keys for other users")

    try:
        totp_response = vault_client.secrets.totp.generate_code(name=key_name)
        return {
            "key_name": key_name,
            "code": totp_response["data"]["code"]
        }
    except hvac.exceptions.VaultError:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="TOTP key definition not found")
